const WORLD_EVENTS=[{"id":"evt_eridu_first","year":-5400,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"Eridu 建城 · 苏美尔的第一座城市","one":"约前 5400 年，Eridu 建立，被苏美尔人尊为世界第一座城市，灌溉农业在此起步。"},{"id":"evt_uruk_period","year":-4500,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"Uruk 时期开始 · 城市化革命","one":"一群村庄合并成 4 万人的超级城市，文明从此进入\"高密度模式\"."},{"id":"evt_cuneiform_invented","year":-3300,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"楔形文字诞生 · 人类第一次把声音变成符号","one":"为了管账，苏美尔人发明了文字 — 然后才发现它能写诗。"},{"id":"evt_egypt_unification","year":-3200,"region":"非洲","civ":"egypt_predynastic","civName":"egypt_predynastic","title":"上下埃及统一 · Narmer 建立第一王朝","one":"约前 3100 年，Narmer 战胜下埃及，开创延续 3000 年的法老王朝。"},{"id":"evt_royal_tombs_ur","year":-2700,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"Ur 王陵 · 王权与殉葬的极致","one":"一个女王带着 52 个殉葬者下葬 — 苏美尔王权达到顶峰也开始走向阴影."},{"id":"evt_step_pyramid","year":-2650,"region":"非洲","civ":"egypt_old","civName":"古埃及·古王国","title":"萨卡拉阶梯金字塔 · 人类第一座石造大建筑","one":"伊姆霍特普为法老乔赛尔设计的六级阶梯金字塔,是人类用石头盖起的第一座巨型建筑。"},{"id":"evt_indus_peak","year":-2600,"region":"南亚","civ":"indus","civName":"印度河文明","title":"印度河城市巅峰 · Mohenjo-Daro 的奇迹","one":"约前 2500 年，Mohenjo-Daro 与 Harappa 进入巅峰，是古代世界城市规划的奇迹，却无宫殿无王陵。"},{"id":"evt_great_pyramid","year":-2589,"region":"非洲","civ":"egypt_old","civName":"古埃及·古王国","title":"Khufu 大金字塔建成 · 人类最大单体建筑","one":"约前 2560 年，Khufu 完成 146 米高的吉萨大金字塔，3800 年内地球最高建筑。"},{"id":"evt_giza_complex","year":-2570,"region":"非洲","civ":"egypt_old","civName":"古埃及·古王国","title":"吉萨建筑群 · 狮身人面像与三大金字塔","one":"约前 2500 年，Khafre 建第二金字塔和狮身人面像，与父亲 Khufu 的大金字塔组成吉萨奇观。"},{"id":"evt_lagash_umma_war","year":-2500,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"拉格什-乌玛战争 · 最早有记录的战争与边界条约","one":"约前 2450 年，城邦 Lagash 与 Umma 为争夺农田打了人类最早有文字记录的战争，立下最早的边界条约。"},{"id":"evt_indus_trade","year":-2500,"region":"南亚","civ":"indus","civName":"印度河文明","title":"麦鲁哈的海商 · 印度河的远洋贸易","one":"印度河人建起世界最早的人工船坞，与两河流域(麦鲁哈)跨海通商。"},{"id":"evt_lugalzagesi","year":-2350,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"卢伽尔扎克西 · 苏美尔的第一次统一","one":"乌玛王击败众城邦,第一次把苏美尔捏成一个国家——却很快败给萨尔贡。"},{"id":"evt_pyramid_texts","year":-2350,"region":"非洲","civ":"egypt_old","civName":"古埃及·古王国","title":"金字塔文 · 世界最古老的宗教文献","one":"刻在第五王朝末代法老乌纳斯金字塔内壁的咒语,是人类已知最古老的宗教文集。"},{"id":"evt_sargon_conquest","year":-2340,"region":"西亚·中东","civ":"akkad","civName":"阿卡德帝国","title":"Sargon 征服 · 人类第一个帝国","one":"前 2334 年，Sargon 从倒酒侍童一路征服，建立第一个跨民族帝国。"},{"id":"evt_enheduanna","year":-2285,"region":"西亚·中东","civ":"akkad","civName":"阿卡德帝国","title":"恩赫杜安娜 · 人类第一位留名作者","one":"萨尔贡之女、乌尔月神大祭司,写下署名的赞美诗——人类已知最早留下名字的作者。"},{"id":"evt_naramsin_empire","year":-2254,"region":"西亚·中东","civ":"akkad","civName":"阿卡德帝国","title":"Naram-Sin 称神 · 阿卡德帝国顶峰","one":"约前 2254 年，Sargon 之孙 Naram-Sin 自称\"神\"，阿卡德帝国达到极盛，首开\"君主神化\"。"},{"id":"evt_akkad_collapse","year":-2200,"region":"西亚·中东","civ":"akkad","civName":"阿卡德帝国","title":"阿卡德帝国的崩溃 · 最早的\"帝国兴衰\"","one":"人类第一个帝国,在干旱、入侵与叛乱中崩溃——给后世留下\"帝国会衰亡\"的第一课。"},{"id":"evt_mk_reunification","year":-2134,"region":"非洲","civ":"egypt_mid","civName":"古埃及·中王国","title":"蒙图霍特普二世重新统一 · 中王国开端","one":"底比斯王蒙图霍特普二世结束 150 年分裂,重新统一埃及,开创\"中王国\"古典时代。"},{"id":"evt_urnammu_law","year":-2112,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"Ur-Nammu 法典 · 已知最早的成文法","one":"约前 2100 年，苏美尔 Ur 第三王朝的 Ur-Nammu 颁布人类已知最早的成文法典，比汉谟拉比早 300 年。"},{"id":"evt_gilgamesh_epic","year":-2100,"region":"西亚·中东","civ":"sumer","civName":"苏美尔","title":"《吉尔伽美什史诗》· 人类第一部文学","one":"一个国王面对挚友之死、追寻永生的故事,成为人类最早的伟大文学,比荷马早约 1500 年。"},{"id":"evt_knossos_palace","year":-1900,"region":"欧洲","civ":"minoan","civName":"米诺斯","title":"克诺索斯宫殿 · 欧洲第一座宫殿","one":"约前 1900 年，米诺斯人在克里特岛建成克诺索斯宫殿，是欧洲第一个高级文明的中心，米诺陶迷宫传说的原型。"},{"id":"evt_indus_decline","year":-1900,"region":"南亚","civ":"indus","civName":"印度河文明","title":"印度河文明衰落 · 至今未解的谜","one":"约前 1900 年起，印度河文明的城市被陆续遗弃，原因至今成谜——可能是河流改道+气候变化。"},{"id":"evt_sinuhe","year":-1900,"region":"非洲","civ":"egypt_mid","civName":"古埃及·中王国","title":"《西努赫的故事》· 古埃及文学的巅峰","one":"一个流亡又归乡的埃及贵族的故事,是古埃及最杰出的文学作品;中期埃及语成为千年古典范本。"},{"id":"evt_senusret3_nubia","year":-1860,"region":"非洲","civ":"egypt_mid","civName":"古埃及·中王国","title":"辛努塞尔特三世 · 征服努比亚与中央集权","one":"中王国最强法老深入征服努比亚、修建要塞链,并削平地方诸侯、强化中央。"},{"id":"evt_faiyum","year":-1840,"region":"非洲","civ":"egypt_mid","civName":"古埃及·中王国","title":"法尤姆开发与\"迷宫\" · 中王国繁荣顶峰","one":"阿蒙内姆赫特三世大兴法尤姆绿洲水利,建造希腊人惊叹的\"迷宫\",把中王国推向繁荣顶点。"},{"id":"evt_hammurabi_code","year":-1792,"region":"西亚·中东","civ":"babylon","civName":"古巴比伦","title":"汉谟拉比法典颁布 · 282 条改变法律史","one":"前 1750 年，巴比伦王汉谟拉比颁布 282 条法典，刻在 2.25 米玄武岩柱上。"},{"id":"evt_hittite_sack_babylon","year":-1750,"region":"西亚·中东","civ":"babylon","civName":"古巴比伦","title":"赫梯洗劫巴比伦 · 古巴比伦王朝终结","one":"约前 1595 年，赫梯王 Mursili I 远征千里突袭巴比伦城，终结了汉谟拉比建立的古巴比伦第一王朝。"},{"id":"evt_enuma_elish","year":-1750,"region":"西亚·中东","civ":"babylon","civName":"古巴比伦","title":"《创世史诗》· 马尔杜克升为众神之王","one":"巴比伦用一部创世神话，把城邦小神马尔杜克升格为宇宙主宰，影响后世《创世记》。"},{"id":"evt_hyksos_expulsion","year":-1650,"region":"非洲","civ":"egypt_new","civName":"古埃及·新王国","title":"驱逐希克索斯 · 埃及新王国开端","one":"约前 1550 年，法老 Ahmose 把外族统治者希克索斯赶出埃及，开创强盛的新王国。"},{"id":"evt_minoan_fall","year":-1628,"region":"欧洲","civ":"minoan","civName":"米诺斯","title":"迈锡尼征服克里特 · 米诺斯文明终结","one":"约前 1450 年，希腊大陆的迈锡尼人控制克里特，欧洲第一个文明被取代。"},{"id":"evt_telepinu","year":-1620,"region":"西亚·中东","civ":"hittite","civName":"赫梯帝国","title":"《帖利平努法令》· 最早的\"继承法\"","one":"约前 1525 年，赫梯王帖利平努颁布王位继承法，被视为人类早期宪政雏形。"},{"id":"evt_thera_eruption","year":-1600,"region":"欧洲","civ":"minoan","civName":"米诺斯","title":"Thera 火山爆发 · 摧毁米诺斯文明的导火索","one":"约前 1600 年，爱琴海 Thera 岛（今 Santorini）发生历史上最大火山爆发之一，可能直接打击米诺斯文明。"},{"id":"evt_punt_expedition","year":-1470,"region":"非洲","civ":"egypt_new","civName":"古埃及·新王国","title":"哈特谢普苏特的蓬特远征","one":"女法老派船队远航神秘的\"蓬特之地\",带回乳香、没药与异域珍宝。"},{"id":"evt_akhenaten_reform","year":-1353,"region":"非洲","civ":"egypt_new","civName":"古埃及·新王国","title":"Akhenaten 一神教改革 · 人类第一次废除多神","one":"约前 1348 年，Akhenaten 废除埃及所有传统神，强制全国只崇拜太阳神 Aten。"},{"id":"evt_pangeng_relocate","year":-1300,"region":"东亚","civ":"shang","civName":"商朝","title":"盘庚迁殷 · 商朝从游牧走向定居","one":"约前 1300 年，商王盘庚把都城迁到殷（今安阳），商朝从此稳定 273 年。"},{"id":"evt_kadesh","year":-1274,"region":"非洲","civ":"egypt_new","civName":"古埃及·新王国","title":"卡迭石战役 · 古代世界最大战车战","one":"前 1274 年，Ramesses II 与赫梯王 Muwatalli II 在卡迭石打了 5000+ 战车的大战，平手。"},{"id":"evt_wuding_peak","year":-1250,"region":"东亚","civ":"shang","civName":"商朝","title":"武丁中兴 · 商朝巅峰","one":"武丁在位 59 年（约前 1250-1192），商朝达到鼎盛，他妻子妇好成为中国第一位女将军。"},{"id":"evt_oracle_bones","year":-1250,"region":"东亚","civ":"shang","civName":"商朝","title":"甲骨文 · 汉字的源头","one":"商王刻在龟甲兽骨上的占卜记录,是中国最早的成熟文字,汉字由此一脉相承至今。"},{"id":"evt_merneptah_stele","year":-1208,"region":"非洲","civ":"egypt_new","civName":"古埃及·新王国","title":"麦伦普塔石碑 · 最早提到\"以色列\"的文字","one":"拉美西斯二世之子的胜利石碑,留下了世界上最早的\"以色列\"一词记录。"},{"id":"evt_bronze_collapse","year":-1200,"region":"欧洲","civ":"collapse","civName":"collapse","title":"青铜时代大崩溃 · 8 大文明同时倒下","one":"前 1177 年起 50 年内，地中海+近东 8 个文明（赫梯/迈锡尼/Ugarit/塞浦路斯/...）同时崩溃。"},{"id":"evt_sea_peoples","year":-1200,"region":"欧洲","civ":"collapse","civName":"collapse","title":"海上民族入侵 · 青铜文明的掘墓人","one":"约前 1200-1177 年，神秘的\"海上民族\"席卷地中海东岸，摧毁城市，是青铜时代大崩溃的关键推手。"},{"id":"evt_shang_bronze","year":-1200,"region":"东亚","civ":"shang","civName":"商朝","title":"商代青铜器 · 礼制与权力的化身","one":"以陶范法铸造的饕餮纹青铜礼器,是商文明的巅峰——后母戊大方鼎重达 832 公斤。"},{"id":"evt_battle_muye","year":-1075,"region":"东亚","civ":"shang","civName":"商朝","title":"牧野之战 · 商朝灭亡","one":"前 1046 年，周武王率联军在牧野（今河南汲县）击败商纣王，商朝结束。"},{"id":"evt_alphabet","year":-1050,"region":"西亚·中东","civ":"phoenicia","civName":"腓尼基","title":"腓尼基字母 · 书写的革命","one":"约前1050年，腓尼基人创22辅音字母，成为今天几乎所有字母的祖先。"},{"id":"evt_wuwang_zhou","year":-1046,"region":"东亚","civ":"xizhou","civName":"西周","title":"武王伐纣 · 西周建立","one":"前1046年，周武王牧野之战灭商，建立周朝，开启古典中国。"},{"id":"evt_zhougong","year":-1040,"region":"东亚","civ":"xizhou","civName":"西周","title":"周公制礼作乐 · 营建洛邑","one":"约前1040年，周公平定三监之乱、制礼作乐、分封宗法，奠定中华文明的根。"},{"id":"evt_israel_kingdom","year":-1000,"region":"西亚·中东","civ":"israel","civName":"以色列·犹大","title":"以色列联合王国 · 大卫与所罗门","one":"约前1000年，大卫定都耶路撒冷、所罗门建第一圣殿，一神教成型。"},{"id":"evt_olympics","year":-776,"region":"欧洲","civ":"greece_classical","civName":"古典希腊","title":"古代奥林匹克运动会","one":"前776年，首届奥运会在奥林匹亚举行，敌对城邦休战同场竞技。"},{"id":"evt_babylon_captivity","year":-597,"region":"西亚·中东","civ":"neobabylon","civName":"新巴比伦","title":"巴比伦之囚","one":"前586年，尼布甲尼撒灭犹大、毁第一圣殿，掳犹太人至巴比伦。"},{"id":"evt_solon","year":-594,"region":"欧洲","civ":"greece_classical","civName":"古典希腊","title":"梭伦改革","one":"约前594年，梭伦废除债务奴隶、按财产分级，为雅典民主奠基。"},{"id":"evt_cyrus_found","year":-550,"region":"西亚·中东","civ":"achaemenid","civName":"波斯帝国","title":"居鲁士缔造波斯帝国","one":"约前550–539年，居鲁士接连征服米底、吕底亚、巴比伦，建立人类第一个世界帝国。"},{"id":"evt_buddha","year":-528,"region":"南亚","civ":"magadha","civName":"摩揭陀·佛陀","title":"佛陀菩提树下开悟","one":"约前528年，悉达多在菩提树下悟道成佛，创立佛教。"},{"id":"evt_roman_founded","year":-509,"region":"欧洲","civ":"roman_republic","civName":"罗马共和国","title":"罗马共和国的建立","one":"前509年，罗马人推翻暴君国王，建立共和国，开创分权制衡。"},{"id":"evt_confucius","year":-497,"region":"东亚","civ":"chunqiu","civName":"春秋","title":"孔子周游列国","one":"前497–484年，孔子率弟子周游十四年推行仁政，虽不得用，却奠定儒家。"},{"id":"evt_marathon","year":-490,"region":"西亚·中东","civ":"achaemenid","civName":"波斯帝国","title":"希波战争 · 马拉松与萨拉米斯","one":"前490/480年，希腊城邦以弱胜强击退波斯两次入侵，保住西方文明火种。"},{"id":"evt_first_council","year":-483,"region":"南亚","civ":"magadha","civName":"摩揭陀·佛陀","title":"佛教第一次结集","one":"约前483年，佛陀涅槃后五百罗汉结集，整理出佛教经律。"},{"id":"evt_socrates_death","year":-399,"region":"欧洲","civ":"greece_classical","civName":"古典希腊","title":"苏格拉底之死","one":"前399年，雅典以\"亵渎神明、败坏青年\"判处苏格拉底死刑，他从容饮鸩。"},{"id":"evt_shangyang","year":-356,"region":"东亚","civ":"zhanguo","civName":"战国","title":"商鞅变法","one":"约前356–350年，商鞅在秦两次变法，把秦改造成战国最强的战争机器。"},{"id":"evt_maling","year":-353,"region":"东亚","civ":"zhanguo","civName":"战国","title":"围魏救赵 · 马陵之战","one":"前353/341年，孙膑两次用谋大败庞涓，\"减灶诱敌\"成军事经典。"},{"id":"evt_alexander","year":-334,"region":"欧洲","civ":"macedon","civName":"马其顿·亚历山大","title":"亚历山大东征","one":"前334–323年，亚历山大十三年征服波斯到印度河，开启希腊化时代。"},{"id":"evt_punic","year":-264,"region":"欧洲","civ":"roman_republic","civName":"罗马共和国","title":"布匿战争","one":"前264–146年，罗马三次战胜迦太基，称霸地中海。"},{"id":"evt_ashoka","year":-261,"region":"南亚","civ":"maurya","civName":"孔雀王朝","title":"阿育王皈依佛教 · 弘法","one":"约前260年，阿育王在羯陵伽血战后皈依佛教，立法敕、派传教团。"},{"id":"evt_qin_unify","year":-230,"region":"东亚","civ":"qin","civName":"秦朝","title":"秦统一六国","one":"前230–221年，秦王嬴政十年灭六国，建立中国第一个中央集权帝国。"},{"id":"evt_jingke","year":-227,"region":"东亚","civ":"qin","civName":"秦朝","title":"荆轲刺秦王","one":"前227年，荆轲\"图穷匕见\"刺杀秦王嬴政未遂，慷慨赴死。"},{"id":"evt_chenshengwuguang","year":-209,"region":"东亚","civ":"qin","civName":"秦朝","title":"大泽乡起义 · 陈胜吴广","one":"前209年，陈胜吴广喊出\"王侯将相宁有种乎\"，点燃反秦烈火。"},{"id":"evt_chuhan","year":-206,"region":"东亚","civ":"qin","civName":"秦朝","title":"楚汉相争 · 鸿门宴到垓下","one":"前206–202年，项羽与刘邦逐鹿天下，从鸿门宴到四面楚歌。"},{"id":"evt_wenjing","year":-180,"region":"东亚","civ":"xihan","civName":"西汉","title":"文景之治","one":"前180–141年，汉文帝汉景帝行黄老无为、轻徭薄赋，开创汉初盛世。"},{"id":"evt_zhangqian","year":-138,"region":"东亚","civ":"xihan","civName":"西汉","title":"张骞通西域 · 丝绸之路","one":"前138/119年，张骞两次出使西域，开通连接东西方的丝绸之路。"},{"id":"evt_duzun_ruxue","year":-134,"region":"东亚","civ":"xihan","civName":"西汉","title":"独尊儒术","one":"约前134年，汉武帝采董仲舒议\"罢黜百家、独尊儒术\"，儒家成国家正统。"},{"id":"evt_han_xiongnu","year":-129,"region":"东亚","civ":"xihan","civName":"西汉","title":"汉匈战争 · 卫青霍去病反击匈奴","one":"前129–119年，汉武帝派卫青、霍去病三击匈奴，解除北方百年威胁。"},{"id":"evt_suwu","year":-100,"region":"东亚","civ":"xihan","civName":"西汉","title":"苏武牧羊","one":"前100年，苏武出使匈奴被扣十九年，持节不降，\"留胡节不辱\"。"},{"id":"evt_spartacus_revolt","year":-73,"region":"欧洲","civ":"roman_republic","civName":"罗马共和国","title":"斯巴达克斯起义","one":"前73–71年，角斗士斯巴达克斯领导罗马史上最大奴隶起义。"},{"id":"evt_caesar","year":-58,"region":"欧洲","civ":"roman_republic","civName":"罗马共和国","title":"恺撒跨过卢比孔河","one":"前49年，恺撒率军渡卢比孔河，引爆内战，终结罗马共和国。"},{"id":"evt_pax_romana","year":-31,"region":"欧洲","civ":"roman_empire","civName":"罗马帝国","title":"奥古斯都 · 罗马和平","one":"前27年，屋大维建元首制，开启约两百年的\"罗马和平\"。"},{"id":"evt_assyria_empire","year":-9,"region":"西亚·中东","civ":"assyria","civName":"新亚述","title":"新亚述帝国 · 铁血与图书馆","one":"前9–7世纪，新亚述以铁器军团征服西亚，亚述巴尼拔建尼尼微图书馆。"},{"id":"evt_homer","year":-8,"region":"欧洲","civ":"greece_classical","civName":"古典希腊","title":"荷马史诗","one":"约前8世纪，《伊利亚特》《奥德赛》成文，奠定希腊价值观与西方文学。"},{"id":"evt_alexandria","year":-3,"region":"欧洲","civ":"hellenistic","civName":"希腊化世界","title":"亚历山大里亚 · 希腊化科学巅峰","one":"前3世纪，托勒密在亚历山大里亚建图书馆与博学园，古代科学达到顶峰。"},{"id":"evt_daoism","year":2,"region":"东亚","civ":"donghan","civName":"东汉","title":"道教的兴起 · 五斗米道与太平道","one":"公元2世纪，张道陵创天师道、张角创太平道，道家思想组织化为道教。"},{"id":"evt_wangmang","year":8,"region":"东亚","civ":"xihan","civName":"西汉","title":"王莽改制 · 新朝","one":"公元9–23年，王莽篡汉建\"新\"，托古改制全面失败，天下大乱。"},{"id":"evt_jesus","year":30,"region":"欧洲","civ":"christianity","civName":"基督教兴起","title":"耶稣传道与受难","one":"约公元30年，耶稣在犹太行省传道、被钉十字架，门徒信其复活，基督教由此发端。"},{"id":"evt_jewish_war","year":66,"region":"欧洲","civ":"christianity","civName":"基督教兴起","title":"犹太战争 · 第二圣殿被毁","one":"公元66–73年，犹太人反抗罗马失败，70年第二圣殿被毁，犹太人大流散。"},{"id":"evt_pompeii","year":79,"region":"欧洲","civ":"roman_empire","civName":"罗马帝国","title":"庞贝末日 · 维苏威火山爆发","one":"公元79年，维苏威火山爆发，瞬间掩埋繁华的庞贝古城。"},{"id":"evt_ganying","year":97,"region":"东亚","civ":"donghan","civName":"东汉","title":"甘英探大秦 · 汉与罗马的遥望","one":"公元97年班超派甘英出使罗马(大秦)，抵波斯湾而返——两大帝国最近的一次接触。"},{"id":"evt_cailun","year":105,"region":"东亚","civ":"donghan","civName":"东汉","title":"蔡伦改进造纸术","one":"约公元105年，蔡伦用树皮麻布造出廉价纸张，改变了人类信息传播。"},{"id":"evt_zhangheng","year":132,"region":"东亚","civ":"donghan","civName":"东汉","title":"张衡与候风地动仪","one":"132年，张衡发明世界最早的地震仪\"候风地动仪\"。"},{"id":"evt_sanguo","year":184,"region":"东亚","civ":"donghan","civName":"东汉","title":"黄巾起义与三国鼎立","one":"184年黄巾起义动摇东汉，群雄逐鹿，终成魏蜀吴三国鼎立。"},{"id":"evt_crisis3","year":235,"region":"欧洲","civ":"roman_empire","civName":"罗马帝国","title":"三世纪危机","one":"235–284年，罗马五十年间约换五十帝，蛮族入侵、瘟疫与通胀几乎让帝国解体。"},{"id":"evt_maya_classic","year":250,"region":"美洲","civ":"maya","civName":"玛雅","title":"玛雅古典文明","one":"约250–900年,玛雅城邦在中美洲创造文字、历法与金字塔,后神秘崩溃。"},{"id":"evt_milan","year":303,"region":"欧洲","civ":"christianity","civName":"基督教兴起","title":"《米兰敕令》· 基督教合法化","one":"313年，君士坦丁颁布《米兰敕令》，结束对基督教三百年的迫害。"},{"id":"evt_gupta_golden","year":320,"region":"南亚","civ":"gupta","civName":"笈多王朝","title":"笈多黄金时代 · \"零\"的诞生","one":"4–5世纪，笈多王朝创\"零\"与十进制、阿耶波多天文学，印度科学达顶峰。"},{"id":"evt_justinian_law","year":537,"region":"欧洲","civ":"byzantine","civName":"拜占庭","title":"查士丁尼法典与圣索菲亚","one":"6世纪，查士丁尼编纂罗马法、建圣索菲亚大教堂，重现罗马辉煌。"},{"id":"evt_hijra","year":610,"region":"西亚·中东","civ":"islam_rise","civName":"伊斯兰·早期哈里发","title":"希吉拉 · 伊斯兰教创立","one":"622年穆罕默德迁麦地那(伊斯兰元年),创立伊斯兰教并统一阿拉伯。"},{"id":"evt_tang_zhenguan","year":627,"region":"东亚","civ":"tang","civName":"唐朝","title":"贞观之治","one":"627–649年,唐太宗虚心纳谏、轻徭薄赋,开创盛世,被尊\"天可汗\"。"},{"id":"evt_xuanzang_journey","year":629,"region":"东亚","civ":"tang","civName":"唐朝","title":"玄奘西行取经","one":"629–645年,玄奘历尽艰险赴印度求法,带回并翻译大量佛经。"},{"id":"evt_arab_conquest","year":636,"region":"西亚·中东","civ":"islam_rise","civName":"伊斯兰·早期哈里发","title":"阿拉伯大征服","one":"632–661年,四大哈里发二十年间击败拜占庭与波斯,建横跨三洲帝国。"},{"id":"evt_greekfire","year":674,"region":"欧洲","civ":"byzantine","civName":"拜占庭","title":"希腊火与圣像破坏运动","one":"717–843年,拜占庭以\"希腊火\"守住君士坦丁堡,又陷入百年圣像之争。"},{"id":"evt_karbala","year":680,"region":"西亚·中东","civ":"islam_rise","civName":"伊斯兰·早期哈里发","title":"卡尔巴拉惨案 · 逊尼什叶分裂","one":"680年,先知外孙侯赛因在卡尔巴拉被倭马亚军杀害,什叶派分裂定型。"},{"id":"evt_wuzetian","year":690,"region":"东亚","civ":"tang","civName":"唐朝","title":"武则天称帝","one":"690年,武则天称帝建\"周\",成为中国历史上唯一的女皇帝。"},{"id":"evt_tours","year":732,"region":"欧洲","civ":"franks","civName":"法兰克·加洛林","title":"图尔之战","one":"732年,查理·马特击退伊斯兰军队北进,阻止其深入西欧。"},{"id":"evt_abbasid_baghdad","year":750,"region":"西亚·中东","civ":"abbasid","civName":"阿拔斯·巴格达","title":"阿拔斯革命与巴格达建城","one":"750年阿拔斯推翻倭马亚,762年曼苏尔建巴格达\"和平之城\"。"},{"id":"evt_talas","year":751,"region":"西亚·中东","civ":"abbasid","civName":"阿拔斯·巴格达","title":"怛罗斯之战 · 造纸术西传","one":"751年唐军与阿拔斯军在中亚交战,唐败,造纸术由战俘西传伊斯兰。"},{"id":"evt_anshi_rebellion","year":755,"region":"东亚","civ":"tang","civName":"唐朝","title":"安史之乱","one":"755–763年,安禄山史思明叛乱,唐朝由盛转衰的转折点。"},{"id":"evt_cordoba","year":756,"region":"西亚·中东","civ":"islam_rise","civName":"伊斯兰·早期哈里发","title":"科尔多瓦 · 欧洲的明珠","one":"8–11世纪,后倭马亚的科尔多瓦成为欧洲最繁华、最有学问的城市。"},{"id":"evt_house_wisdom","year":762,"region":"西亚·中东","civ":"abbasid","civName":"阿拔斯·巴格达","title":"巴格达智慧宫 · 伊斯兰黄金时代","one":"9世纪,阿拔斯巴格达智慧宫翻译并发展希腊/印度知识,创代数。"},{"id":"evt_viking_age","year":793,"region":"欧洲","civ":"vikings","civName":"维京","title":"维京时代","one":"793年劫掠林迪斯法恩开启维京时代,北欧人横扫欧洲海岸。"},{"id":"evt_heiankyo","year":794,"region":"东亚","civ":"heian","civName":"平安日本","title":"迁都平安京 · 国风文化","one":"794年日本迁都平安京,消化唐风后发展出独特的\"国风文化\"。"},{"id":"evt_charlemagne","year":800,"region":"欧洲","civ":"franks","civName":"法兰克·加洛林","title":"查理曼加冕","one":"800年,教皇为查理曼加冕\"罗马人的皇帝\",西欧重现帝国。"},{"id":"evt_charlemagne_crown","year":800,"region":"欧洲","civ":"franks","civName":"法兰克·加洛林","title":"查理曼加冕 · 加洛林文艺复兴","one":"800年圣诞,教皇为查理曼加冕\"罗马人的皇帝\",西方帝国复兴。"},{"id":"evt_verdun","year":843,"region":"欧洲","civ":"franks","civName":"法兰克·加洛林","title":"凡尔登条约 · 欧洲三分","one":"843年,查理曼三个孙子瓜分帝国,法/德/中间王国雏形由此而来。"},{"id":"evt_chola","year":850,"region":"南亚","civ":"chola","civName":"朱罗帝国","title":"朱罗帝国的海上霸权","one":"11世纪朱罗帝国建宏伟神庙、派海军远征东南亚,称霸孟加拉湾。"},{"id":"evt_kievan_founded","year":862,"region":"欧洲","civ":"kievan_rus","civName":"基辅罗斯","title":"基辅罗斯的建立","one":"862–882年,瓦良格人留里克、奥列格统一诺夫哥罗德与基辅。"},{"id":"evt_huangchao","year":875,"region":"东亚","civ":"tang","civName":"唐朝","title":"黄巢起义 · 唐朝灭亡","one":"875–907年,黄巢起义重创唐朝,朱温篡唐,中国进入五代十国。"},{"id":"evt_song_founding","year":960,"region":"东亚","civ":"song","civName":"宋朝","title":"陈桥兵变 · 重文抑武","one":"960年赵匡胤陈桥兵变建宋,\"杯酒释兵权\"开启文官治国。"},{"id":"evt_rus_baptism","year":988,"region":"欧洲","civ":"kievan_rus","civName":"基辅罗斯","title":"罗斯受洗","one":"988年,弗拉基米尔皈依东正教,奠定俄罗斯文明的根基。"},{"id":"evt_vinland","year":1000,"region":"欧洲","civ":"vikings","civName":"维京","title":"维京抵达北美 · 文兰","one":"约1000年,莱夫·埃里克松抵达北美,比哥伦布早约五百年。"},{"id":"evt_genji","year":1008,"region":"东亚","civ":"heian","civName":"平安日本","title":"《源氏物语》与平安国风文化","one":"约1008年,紫式部著《源氏物语》,日本国风文化的巅峰。"},{"id":"evt_srivijaya","year":1025,"region":"东南亚","civ":"srivijaya","civName":"室利佛逝","title":"室利佛逝海上帝国","one":"7–13世纪,室利佛逝(三佛齐)控制马六甲海峡,称霸东南亚海上佛教贸易。"},{"id":"evt_great_schism","year":1054,"region":"欧洲","civ":"byzantine","civName":"拜占庭","title":"东西教会大分裂","one":"1054年,罗马教廷与君士坦丁堡牧首互相绝罚,基督教永久分裂为天主教与东正教。"},{"id":"evt_manzikert","year":1071,"region":"欧洲","civ":"byzantine","civName":"拜占庭","title":"曼兹科特战役","one":"1071年塞尔柱突厥大败拜占庭、俘其皇帝,小亚细亚渐失,催生十字军。"},{"id":"evt_universities","year":1088,"region":"欧洲","civ":"medieval_europe","civName":"中世纪欧洲","title":"中世纪大学的兴起","one":"11–13世纪欧洲诞生博洛尼亚、巴黎、牛津等大学,现代大学的源头。"},{"id":"evt_crusades","year":1095,"region":"欧洲","civ":"crusades","civName":"十字军","title":"十字军东征","one":"1096–1291年,西欧基督徒东征夺圣地,深刻改变欧洲与东方关系。"},{"id":"evt_first_crusade","year":1095,"region":"欧洲","civ":"crusades","civName":"十字军","title":"第一次十字军 · 攻占耶路撒冷","one":"1096–1099年第一次十字军东征,1099年攻占耶路撒冷,建十字军国家。"},{"id":"evt_great_zimbabwe","year":1100,"region":"非洲","civ":"great_zimbabwe","civName":"大津巴布韦","title":"大津巴布韦石城","one":"约11–15世纪,绍纳人建起撒哈拉以南最宏伟的石城,黄金贸易的中心。"},{"id":"evt_jingkang","year":1127,"region":"东亚","civ":"song","civName":"宋朝","title":"靖康之变","one":"1127年,金兵攻破开封掳走徽钦二帝,北宋灭亡,宋室南渡。"},{"id":"evt_samurai","year":1180,"region":"东亚","civ":"heian","civName":"平安日本","title":"武士的兴起","one":"平安后期武士崛起,源平争霸,开启日本数百年的武家政治。"},{"id":"evt_kamakura","year":1185,"region":"东亚","civ":"shogunate","civName":"幕府日本","title":"镰仓幕府的建立","one":"1192年源赖朝任征夷大将军,建镰仓幕府,武士统治日本之始。"},{"id":"evt_saladin","year":1187,"region":"欧洲","civ":"crusades","civName":"十字军","title":"萨拉丁收复耶路撒冷","one":"1187年哈丁战役后,萨拉丁收复耶路撒冷,成为伊斯兰与西方共敬的骑士。"},{"id":"evt_delhi","year":1192,"region":"南亚","civ":"delhi_sultanate","civName":"德里苏丹国","title":"德里苏丹国的建立","one":"1206年突厥将领在北印度建立德里苏丹国,伊斯兰统治印度之始,并挡住蒙古。"},{"id":"evt_genghis_unify","year":1206,"region":"东亚","civ":"mongol","civName":"蒙古帝国·元","title":"成吉思汗统一蒙古","one":"1206年,铁木真统一草原各部,被尊\"成吉思汗\",建蒙古国。"},{"id":"evt_magna_carta","year":1215,"region":"欧洲","civ":"medieval_europe","civName":"中世纪欧洲","title":"大宪章","one":"1215年英格兰贵族迫约翰王签《大宪章》,\"王权受法律约束\"的里程碑。"},{"id":"evt_mongol_conquest","year":1258,"region":"东亚","civ":"mongol","civName":"蒙古帝国·元","title":"蒙古西征 · 最大陆地帝国","one":"13世纪,蒙古铁骑横扫欧亚,建立人类史上最大连续陆地帝国。"},{"id":"evt_yuan_kublai","year":1271,"region":"东亚","civ":"mongol","civName":"蒙古帝国·元","title":"忽必烈建元 · 马可·波罗","one":"1271年忽必烈建元朝、定都大都,接见马可·波罗。"},{"id":"evt_kamikaze","year":1274,"region":"东亚","civ":"shogunate","civName":"幕府日本","title":"神风 · 日本抗击蒙古","one":"1274/1281年,忽必烈两征日本,皆遇台风(\"神风\")而败。"},{"id":"evt_mansa_musa","year":1324,"region":"非洲","civ":"mali","civName":"马里帝国","title":"曼萨·穆萨朝觐麦加","one":"1324年,马里君主曼萨·穆萨携巨量黄金朝觐,震动世界。"},{"id":"evt_timbuktu","year":1324,"region":"非洲","civ":"mali","civName":"马里帝国","title":"廷巴克图 · 非洲的学术之城","one":"14–16世纪,马里/桑海的廷巴克图成为撒哈拉以南的黄金贸易与伊斯兰学术中心。"},{"id":"evt_aztec","year":1325,"region":"美洲","civ":"aztec","civName":"阿兹特克","title":"阿兹特克与特诺奇蒂特兰","one":"1325年建特诺奇蒂特兰,15世纪成墨西哥中部强大帝国。"},{"id":"evt_black_death","year":1347,"region":"欧洲","civ":"medieval_europe","civName":"中世纪欧洲","title":"黑死病","one":"1347年起,鼠疫夺走欧洲约三分之一至半人口,震撼旧秩序。"},{"id":"evt_1453","year":1453,"region":"欧洲","civ":"byzantine","civName":"拜占庭","title":"君士坦丁堡陷落","one":"1453年,奥斯曼苏丹用巨炮攻破君堡,千年拜占庭(罗马)终结。"}];
